create table if not exists approvals (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, target_type text not null, target_id bigint, title text not null, client_id bigint references clients(id) on delete set null, project_id bigint references projects(id) on delete set null, status text not null default 'pending', requested_at timestamptz not null default now(), decided_at timestamptz, decision text, comment text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists briefings (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, name text not null, client_id bigint references clients(id) on delete set null, project_id bigint references projects(id) on delete set null, status text not null default 'draft', questions jsonb not null default '[]', responses jsonb not null default '{}', public_token text, approved_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists change_requests (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, project_id bigint references projects(id) on delete set null, client_id bigint references clients(id) on delete set null, title text not null, description text, status text not null default 'pending', impact_days integer default 0, additional_cost numeric(14,2) default 0, approval_data jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists deliveries (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, project_id bigint references projects(id) on delete cascade, version text not null, environment text, published_at timestamptz, responsible text, checklist jsonb not null default '[]', backup_done boolean default false, tests jsonb not null default '{}', published_url text, status text not null default 'draft', client_approved boolean default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists infrastructure_assets (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, client_id bigint references clients(id) on delete set null, project_id bigint references projects(id) on delete set null, kind text not null, name text not null, provider text, expires_on date, cost numeric(14,2) default 0, client_price numeric(14,2) default 0, responsible text, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists knowledge_articles (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, title text not null, body text not null default '', category text, visibility text not null default 'internal', status text not null default 'draft', created_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists forms (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, name text not null, kind text not null, schema jsonb not null default '{}', automation_config jsonb not null default '{}', status text not null default 'draft', public_token text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists payables (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, description text not null, supplier text, project_id bigint references projects(id) on delete set null, client_id bigint references clients(id) on delete set null, amount numeric(14,2) not null default 0, due_at date, paid_at timestamptz, status text not null default 'pending', recurrence text, proof_url text, approved_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists bank_accounts (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, name text not null, kind text not null default 'bank', opening_balance numeric(14,2) not null default 0, current_balance numeric(14,2) not null default 0, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists invoices (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, number text, client_id bigint references clients(id) on delete set null, project_id bigint references projects(id) on delete set null, amount numeric(14,2) not null default 0, issued_on date, status text not null default 'draft', pdf_url text, xml_url text, error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists audit_events (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, actor_id uuid references users(id) on delete set null, action text not null, entity_type text not null, entity_id bigint, changes jsonb not null default '{}', ip_address text, user_agent text, created_at timestamptz not null default now());
create table if not exists trash (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, entity_type text not null, entity_id bigint not null, payload jsonb not null default '{}', deleted_by uuid references users(id) on delete set null, restore_until timestamptz, created_at timestamptz not null default now());
create index if not exists idx_approvals_org_status on approvals(organization_id, status);
create index if not exists idx_briefings_org_status on briefings(organization_id, status);
create index if not exists idx_change_requests_org_status on change_requests(organization_id, status);
create index if not exists idx_deliveries_org_project on deliveries(organization_id, project_id);
create index if not exists idx_infrastructure_org_expiry on infrastructure_assets(organization_id, expires_on);
create index if not exists idx_knowledge_org_status on knowledge_articles(organization_id, status);
create index if not exists idx_payables_org_due on payables(organization_id, due_at, status);
create index if not exists idx_invoices_org_status on invoices(organization_id, status);
create index if not exists idx_audit_events_org_created on audit_events(organization_id, created_at desc);
create index if not exists idx_trash_org_created on trash(organization_id, created_at desc);
